  ref text, commande text, famille text, nom text, description text,
  usage text, entree text, sortie text
);

do $ctrl$
declare n integer;
begin
  select count(*) into n
  from lot_v4 l
  join public.prompts p on p.external_ref = l.ref
  join public.categories c on c.id = p.category_id
  where p.command::text <> l.commande or c.external_ref <> l.famille;
  if n > 0 then
    raise exception '% lignes ne correspondent pas (commande ou famille).', n;
  end if;
end $ctrl$;

update public.prompts p
set name = l.nom,
    short_description = l.description,
    -- Un seul cas d'usage, celui qui dit quand se servir de la commande. Le
    -- second que portait la V3 recopiait la commande dans une phrase.
    use_cases = case when l.usage is null then p.use_cases else array[l.usage] end,
    expected_input = coalesce(l.entree, p.expected_input),
    expected_output = coalesce(l.sortie, p.expected_output),
    result_summary = coalesce(l.sortie, p.result_summary),
    catalog_version = 'images-responsives',
    revised_at = date '2026-09-09'
from lot_v4 l
where p.external_ref = l.ref;

drop table lot_v4;
